import {
	Accessor,
	createContext,
	createEffect,
	createMemo,
	createSignal,
	on,
	onCleanup,
	Setter,
	useContext,
} from "solid-js";

import { InputEngineEvent } from "#core/ui/input/input-support.js";
import { IsControllerActive } from "#core/ui-next/services/input.js";
import { createArraySignal, Mutator } from "#core/ui-next/utilities/solid-utilities.js";

export type Focusable = HTMLElement | FocusContextProvider;
export type FocusNavigationHandler = (context: FocusContextProvider, action: InputNavigationAction) => boolean;
export type FocusEngineInputHandler = (context: FocusContextProvider, event: InputEngineEvent) => boolean;
export type FocusSortOrder = (children: Focusable[]) => void;
export type FocusNavigationRulesMap = Map<InputNavigationAction, (context: FocusContextProvider) => boolean>;

const [solidFocus, setSolidFocus] = createSignal<HTMLElement | null>(null, {
	// Always trigger a signal update
	equals: false,
});

export const currentSolidFocus = solidFocus;

export function buildFocusChain(element: HTMLElement | null, target = document.body) {
	const chain = [];

	while (element && element != target) {
		if (element.hasAttribute("tabindex")) {
			chain.push(new WeakRef(element));
		}
		element = element.parentElement;
	}

	chain.push(new WeakRef(target));

	return chain;
}

/**
 * A type guard which checks if a Focusable is a FocusContextProvider
 * @param focusable
 * @returns
 */
export function isFocusableAFocusContext(focusable: Focusable | undefined): focusable is FocusContextProvider {
	return focusable instanceof FocusContextProvider;
}

/**
 * Gets the DOM element which corresponds to a Focusable
 * @param focusable
 * @returns
 */
export function getFocusableElement(focusable: Focusable | undefined) {
	return isFocusableAFocusContext(focusable) ? focusable.element : focusable;
}

function getTabIndex(element: HTMLElement) {
	return Number(getFocusableElement(element)?.getAttribute("tabindex") ?? 0);
}

//#region  Navigation Rules
/**
 * Common focus sort orders
 */
export const FocusSortOrders = {
	/**
	 * The default way to sort focusbles, which sorts by tabIndex.
	 * If tabIndex is set to -1, it will be reassigned based on the insertion order into the navigation tree.
	 * This should be used for any place where order is relatively static or can be easily calculated
	 * @param children The children to sort
	 */
	byIndex: (children: HTMLElement[]) => {
		children.sort((a, b) => getTabIndex(a) - getTabIndex(b));
	},

	/**
	 * Sorts children by DOM order - this is useful for controls which dynamically add/remove/move child components
	 * This is a more expensive operation than index sorting, so it should only be used in dynamic contexts.
	 * @param children The children to sort
	 */
	byDomOrder: (children: HTMLElement[]) => {
		children.sort((a, b) => {
			const ae = getFocusableElement(a);
			const be = getFocusableElement(b);

			if (!ae || !be) {
				console.warn("FocusSortOrders.byDomOrder failed - no element was associated with a focus context.");
				return 0;
			}

			if (ae === be) {
				return 0;
			}

			const position = ae.compareDocumentPosition(be);

			if (position & (Node.DOCUMENT_POSITION_FOLLOWING | Node.DOCUMENT_POSITION_CONTAINED_BY)) {
				return -1;
			} else if (position & (Node.DOCUMENT_POSITION_PRECEDING | Node.DOCUMENT_POSITION_CONTAINS)) {
				return 1;
			}

			return 0;
		});
	},
};

/**
 * A set of simple focus navigation rules
 */
export const DefaultNavigationRules = {
	/**
	 * Navigates based on up/down input
	 */
	vertical: new Map([
		[InputNavigationAction.UP, (context: FocusContextProvider) => context.focusPrevious()],
		[InputNavigationAction.DOWN, (context: FocusContextProvider) => context.focusNext()],
		[InputNavigationAction.NONE, (context: FocusContextProvider) => context.focusCurrent()],
	]) as FocusNavigationRulesMap,
	verticalReversed: new Map([
		[InputNavigationAction.UP, (context: FocusContextProvider) => context.focusNext()],
		[InputNavigationAction.DOWN, (context: FocusContextProvider) => context.focusPrevious()],
		[InputNavigationAction.NONE, (context: FocusContextProvider) => context.focusCurrent()],
	]) as FocusNavigationRulesMap,

	/**
	 * Navigates based on left/right input
	 */
	horizontal: new Map([
		[InputNavigationAction.LEFT, (context: FocusContextProvider) => context.focusPrevious()],
		[InputNavigationAction.RIGHT, (context: FocusContextProvider) => context.focusNext()],
		[InputNavigationAction.NONE, (context: FocusContextProvider) => context.focusCurrent()],
	]) as FocusNavigationRulesMap,
	horizontalReversed: new Map([
		[InputNavigationAction.LEFT, (context: FocusContextProvider) => context.focusNext()],
		[InputNavigationAction.RIGHT, (context: FocusContextProvider) => context.focusPrevious()],
		[InputNavigationAction.NONE, (context: FocusContextProvider) => context.focusCurrent()],
	]) as FocusNavigationRulesMap,
};
//#endregion Rules

const ENABLE_DEBUG_LOGGING = false;

const logDebug = (...args: unknown[]) => {
	if (ENABLE_DEBUG_LOGGING) {
		console.debug(...args);
	}
};

export const focusableToString = (focusable: Focusable) => {
	if (focusable instanceof HTMLElement) {
		return `HTMLElement(${focusable.dataset.name || focusable.id || focusable.className})`;
	} else {
		return `FocusContextProvider(${focusable.contextName})[${focusable.currentFocusIndex()}]`;
	}
};

//#region FocusContext
/**
 * The FocusContextProvider maintains a live virtual navigation tree used for contoller focus and dispatching navigation and engine events.
 * It is utilized the following components:
 * Panels contain a focus context provider are the top level screen component and handle the interfacing between the legacy UI and UI next.
 * Panels also contain an input proxy which descendants can use to tap into input events that were not already handled.
 * Slots are focus context providers and consumers which are used to organize sub-sections with navigation flows that may differ than the their parent context.
 * Other layouts components (like TabOutput) are specialized versions of slots with their own specific rules.
 * Activatables register themselves with ther containing focus context provider, and are where navigation and engine input events ultimately end up.
 */
export class FocusContextProvider {
	private _currentFocusIndex: Accessor<number>;
	private _setCurrentFocusIndex: Setter<number>;
	private _children: Accessor<Focusable[]>;
	private _mutateChildren: Mutator<Focusable[]>;
	private _hasChildren: Accessor<boolean>;
	private _currentFocus: Accessor<Focusable | undefined>;

	/**
	 * True if this context has children and false otherwise
	 */
	public get hasChildren() {
		return this._hasChildren;
	}

	/**
	 * The sorted, registered children of this component.
	 */
	public get children() {
		return this._children;
	}

	/**
	 * Gets the current index in children that this context is targeting
	 * Use tryApplyFocus or trySetFocus to set the current focus index
	 */
	public get currentFocusIndex() {
		return this._currentFocusIndex;
	}

	/**
	 * The current focused element that this context is targeting
	 */
	public get currentFocus() {
		return this._currentFocus;
	}

	/**
	 * Gets the host element
	 */
	public get element() {
		return this._element();
	}

	public get contextName() {
		return this._contextName;
	}

	/**
	 *
	 * @param _element Constructs a focus context provider
	 * @param navigationHandler
	 * @param sortChildren
	 */
	constructor(
		private _element: Accessor<HTMLElement | undefined>,
		private navigationHandler: FocusNavigationHandler,
		private _contextName: string,
		private sortChildren: FocusSortOrder = FocusSortOrders.byIndex,
	) {
		const parent = useFocusContext();

		const [currentFocusIndex, setCurrrentFocusIndex] = createSignal<number>(-1);
		this._currentFocusIndex = currentFocusIndex;
		this._setCurrentFocusIndex = setCurrrentFocusIndex;

		const [children, mutateChildren] = createArraySignal<Focusable>([]);
		this._children = children;
		this._mutateChildren = mutateChildren;

		this._hasChildren = createMemo(() => this._children().length > 0);
		this._currentFocus = createMemo(() => this._children()[this._currentFocusIndex()]);

		if (parent && parent != this) {
			parent.register(this);
		}

		onCleanup(() => parent?.unregister(this));
	}

	/**
	 * Registers a focusable as a child of this context
	 * Elements which are later disabled, hidden or othewise become not available should be unregistered.
	 * @param focusable
	 * @returns
	 */
	public register(focusable: Focusable | undefined) {
		if (!focusable) {
			return;
		}

		// Don't register children multiple times
		const foundindex = this._children().indexOf(focusable);
		if (foundindex >= 0) {
			const element = getFocusableElement(focusable);
			logDebug(
				`Component tried to register as focusable multiple times - ${element?.dataset.name}|${element?.className}`,
			);
			return;
		}

		logDebug(`FocusContextProvider.register ${focusableToString(this)} -> ${focusableToString(focusable)}`);

		this._mutateChildren((children) => {
			children.push(focusable);
			this.sortChildren(children);
		});

		// If this is focused and we now have children - refocus on children
		if (this._children().length > 1 && document.activeElement == this._element()) {
			this.focusCurrentOrDefault();
		}
	}

	/**
	 * Unregisteres a focusable as a child of this context
	 * @param focusable
	 * @returns
	 */
	public unregister(focusable: Focusable | undefined) {
		if (!focusable) {
			return;
		}

		const foundindex = this._children().indexOf(focusable);
		if (foundindex < 0) {
			return;
		}

		const activeFocusRemoved = this._currentFocusIndex() == foundindex;

		this._mutateChildren((children) => {
			children.splice(foundindex, 1);
		});

		// An element was spliced out of the array, we need to shift the current focus index
		if (this._currentFocusIndex() >= foundindex || this._currentFocusIndex() >= this._children().length) {
			this._setCurrentFocusIndex((i) => i - 1);
		}

		// The current focus was removed, We need to refocus
		if (activeFocusRemoved && getFocusableElement(focusable) == document.activeElement) {
			this.focusCurrent();
		}
	}

	/**
	 * Propagates navigation events to the registered handler
	 * How this is handled is dependent on the component's rules
	 * @param action
	 * @returns
	 */
	public navigate(action: InputNavigationAction) {
		logDebug(`FocusContextProvider.navigate called on ${focusableToString(this)}`);
		return this.navigationHandler(this, action);
	}

	public trySetFocus(index: number) {
		if (index >= this._children().length || index < 0) {
			logDebug(`FocusContextProvider.trySetFocus failed - index out of range (${index})`);
			return false;
		}

		logDebug(`FocusContextProvider.trySetFocus ${focusableToString(this)} to index ${index}`);
		logDebug(`\tNew focus: ${focusableToString(this._children()[index])}`);
		this._setCurrentFocusIndex(index);
		return true;
	}

	/**
	 * Tries to set focus to a specific index, the applies DOM focus to the element
	 * @param index
	 * @returns true if the focus application was successful
	 */
	private tryApplyFocus(index: number, applyDomFocus = true) {
		// always trySetFocus even if a controller is not connected to ensure that the internal state is correct
		// this way if a controller connects later, the correct element will be focused
		if (this.trySetFocus(index)) {
			if (IsControllerActive()) {
				const focusable = this._children()[index];
				const focusableElement = getFocusableElement(focusable);
				if (focusableElement && applyDomFocus) {
					setSolidFocus(focusableElement);
				}
			}
			return true;
		}

		return false;
	}

	/**
	 * Reapplies focus to the currently focused child
	 * @returns
	 */
	public focusCurrent() {
		return this.tryApplyFocus(this._currentFocusIndex());
	}

	/**
	 * Reapplies focus to the currently focused child
	 * @returns
	 */
	public focusCurrentOrDefault() {
		if (this._currentFocusIndex() < 0 && this._hasChildren()) {
			this._setCurrentFocusIndex(0);
		}

		return this.tryApplyFocus(this._currentFocusIndex());
	}

	/**
	 * Attempts to applies focus to the next element
	 * @returns true if the focus update was sucessful and false otherwise
	 */
	public focusNext() {
		for (let curIndex = this._currentFocusIndex() + 1; curIndex < this._children().length; curIndex++) {
			if (this.tryApplyFocus(curIndex)) {
				return true;
			}
		}

		return false;
	}

	/**
	 * Attempts to applies focus to the previous element
	 * @returns true if the focus update was sucessful and false otherwise
	 */
	public focusPrevious() {
		for (let curIndex = this._currentFocusIndex() - 1; curIndex >= 0; curIndex--) {
			if (this.tryApplyFocus(curIndex)) {
				return true;
			}
		}

		return false;
	}

	/**
	 * Manually focus a specific child focusable
	 *
	 * The element or context MUST be a registered child of this context or this will fail.
	 *
	 * @param focusable The focusable to set focus to, must be a registered child of this context
	 * @returns true if the focus update was successful and false otherwise
	 */
	public focusChild(focusable: Focusable | undefined, applyDomFocus = true) {
		if (!focusable) {
			return false;
		}

		const index = this.children().indexOf(focusable);
		logDebug(
			`FocusContextProvider.focusChild called for ${focusableToString(this)} -> ${focusableToString(focusable)}`,
		);
		if (index < 0) {
			console.error(
				"FocusContextProvider.focusChild was called with a focusable that is not a child of this context.",
			);
			return false;
		}

		return this.tryApplyFocus(index, applyDomFocus);
	}

	/**
	 * Manually focus a specific child descendant
	 *
	 * The element or context MUST be a registered descendant of this context or this will fail.
	 *
	 * @param focusable The focusable to set focus to, must be a registered child of this context
	 * @returns true if the focus update was successful and false otherwise
	 */
	public focusDescendant(focusable: Focusable | undefined, applyDomFocus = true): boolean {
		if (!focusable) {
			return false;
		}

		const element = getFocusableElement(focusable);

		if (!element) {
			return false;
		}

		// eslint-disable-next-line @typescript-eslint/no-this-alias
		let treeContext: FocusContextProvider | undefined = this;
		let hasContext = true;

		while (hasContext) {
			hasContext = false;
			for (const child of treeContext.children()) {
				if (getFocusableElement(child) == element) {
					// Final element found
					treeContext.focusChild(child, applyDomFocus);
					return true;
				} else if (isFocusableAFocusContext(child) && getFocusableElement(child)?.contains(element)) {
					// Walk the tree towards the child
					hasContext = true;
					treeContext = child;
				}
			}
		}

		// Tree search failed
		return false;
	}

	public getFocuableChildren() {
		return this._children()
			.map((c) => getFocusableElement(c))
			.filter((c) => c) as HTMLElement[];
	}
}

// The default focus context never handles navigation events
export const rootFocus = new FocusContextProvider(
	() => document.body,
	() => false,
	"root",
	() => false,
);

export const FocusContext = createContext(rootFocus);

export function useFocusContext() {
	try {
		const context = useContext(FocusContext);

		if (!context) {
			throw new Error("Unable to resolve FocusContextProvider");
		}

		return context;
	} catch {
		return undefined;
	}
}
//#endregion FocusContext

//#region Directives
/**
 * A directive which registers a component as Focusable with a parent context
 */
export function isFocusable(element: HTMLElement, isFocusable: Accessor<[boolean, boolean | undefined]>) {
	const focusContext = useContext(FocusContext);

	element.setAttribute("data-focus-context-name", focusContext.contextName);

	// Update the context registration based on focusability
	createEffect(
		on(
			() => isFocusable(),
			([isFocusable, autoFocus]) => {
				if (element.isConnected && isFocusable) {
					if (!element.hasAttribute("tabindex")) {
						element.setAttribute("tabindex", "-1");
					}
					focusContext.register(element);
				} else {
					focusContext.unregister(element);
					element.removeAttribute("tabindex");
				}

				if (autoFocus && isFocusable && focusContext.hasChildren()) {
					focusContext.focusDescendant(element, true);
				}
			},
		),
	);

	// When the component is destroyed, always try to remove it from the focus context
	onCleanup(() => focusContext.unregister(element));
}

export function isContextFocusable(
	element: HTMLElement,
	args: Accessor<[FocusContextProvider, boolean, boolean | undefined]>,
) {
	const parentContext = useContext(FocusContext);

	createEffect(
		on(args, ([context, isFocusable, autoFocus]) => {
			// Update the context registration based on focusability
			if (element.isConnected && isFocusable) {
				parentContext.register(context);
			} else {
				parentContext.unregister(context);
			}

			if (autoFocus && isFocusable && parentContext.hasChildren()) {
				rootFocus.focusDescendant(element, true);
			}
		}),
	);

	// When the component is destroyed, always try to remove it from the focus context
	onCleanup(() => {
		const [context] = args();
		parentContext.unregister(context);
	});
}

//#endregion Directives
